contract Factory {
    address public temp1;
    address public temp2;
    function spawn(address first, address second) external {
        temp1 = first;
        temp2 = second;
        new Exchange{salt: keccak256(abi.encodePacked(first, second))}();
        temp1 = address(0);
        temp2 = address(0);
    }
}

contract Exchange {
    address immutable first;
    address immutable second;
    constructor() {
        Exchange.first = Factory(msg.sender).temp1();
        Exchange.second = Factory(msg.sender).temp2();
    }
}
